package com.minhafazendinha.game

import android.graphics.Color
import android.graphics.drawable.GradientDrawable
import android.os.Bundle
import android.os.SystemClock
import android.view.Gravity
import android.view.View
import android.widget.*
import androidx.appcompat.app.AppCompatActivity

class MainActivity:AppCompatActivity(){
 private lateinit var soundPlayer:AnimalSoundPlayer;private lateinit var stage2d:AnimalStageView;private lateinit var cow3d:Cow3DView;private lateinit var status:TextView
 private var selectedAnimal="vaca";private var selectedEmoji="🐮";private var selectedAccessory="";private var onHome=true;private val prefs by lazy{getSharedPreferences("farm_progress",MODE_PRIVATE)}
 private val animals=listOf(Triple("🐮","Vaca","vaca"),Triple("🐔","Galinha","galinha"),Triple("🐶","Cachorro","cachorro"),Triple("🐴","Cavalo","cavalo"),Triple("🐷","Porco","porco"),Triple("🐑","Ovelha","ovelha"),Triple("🐐","Cabra","cabra"),Triple("🫏","Burro","burro"))
 private var stars:Int get()=prefs.getInt("stars",0);set(v){prefs.edit().putInt("stars",v).apply()};private var hearts:Int get()=prefs.getInt("hearts",0);set(v){prefs.edit().putInt("hearts",v).apply()}
 override fun onCreate(b:Bundle?){super.onCreate(b);soundPlayer=AnimalSoundPlayer(this);showHome()}
 private fun round(color:Int,r:Float=28f,stroke:Int=0)=GradientDrawable().apply{setColor(color);cornerRadius=r;if(stroke!=0)setStroke(3,stroke)}
 private fun base(title:String,sub:String)=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER_HORIZONTAL;setPadding(24,24,24,32);background=GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,intArrayOf(0xFF62C9F3.toInt(),0xFFDDF5B7.toInt())).apply{cornerRadius=0f};addView(TextView(this@MainActivity).apply{text="⭐ $stars     ❤️ $hearts";textSize=19f;gravity=Gravity.END;setTextColor(Color.rgb(92,65,37))});addView(TextView(this@MainActivity).apply{text=title;textSize=29f;gravity=Gravity.CENTER;setTextColor(Color.rgb(91,48,24));setPadding(0,8,0,0)});addView(TextView(this@MainActivity).apply{text=sub;textSize=17f;gravity=Gravity.CENTER;setTextColor(Color.rgb(90,75,55));setPadding(0,7,0,16)})}
 private fun btn(t:String,click:()->Unit)=Button(this).apply{text=t;textSize=19f;isAllCaps=false;minHeight=96;setTextColor(Color.rgb(70,42,20));background=round(0xFFFFE8B7.toInt(),25f,0xFFD39A4B.toInt());var lastTap=0L;setOnClickListener{val now=SystemClock.elapsedRealtime();if(now-lastTap>=280L){lastTap=now;click()}}};private fun p()=LinearLayout.LayoutParams(-1,-2).apply{setMargins(0,8,0,8)};private fun set(c:LinearLayout)=setContentView(ScrollView(this).apply{isFillViewport=true;setBackgroundColor(0xFFDDF5B7.toInt());addView(c,android.view.ViewGroup.LayoutParams(-1,-1))})
 private fun showHome(){onHome=true;soundPlayer.stop();val lake=stars>=15;val c=base("🌻 BICHINHOS & FAZENDINHA","Vamos cuidar dos nossos amigos!");c.addView(TextView(this).apply{text="☀️        ☁️\n🌳     🏡     🌳\n       🐮\n🌿🌻🌿🌻🌿";textSize=46f;gravity=Gravity.CENTER;setPadding(0,8,0,20);background=round(0xAAFFFFFF.toInt(),34f,0xFF8EBB54.toInt())},LinearLayout.LayoutParams(-1,360));listOf(Triple("🔊 SONS DOS BICHINHOS",{showSounds()},true),Triple("🐮 CURRAL — Cuidar",{showCare(0)},true),Triple("🌱 HORTA — Regar e colher",{showFarm(0,false)},true),Triple("🐔 GALINHEIRO — Pegar ovos",{showFarm(2,true)},true),Triple("👕 ARMÁRIO — Animais e roupas",{showLab()},true),Triple(if(lake)"🦆 LAGO — Liberado!" else "🔒 LAGO — Faltam ${15-stars} ⭐",{if(lake)showLake() else Toast.makeText(this,"Ganhe estrelas cuidando da fazendinha! ⭐",Toast.LENGTH_SHORT).show()},true)).forEach{c.addView(btn(it.first,it.second),p())};set(c)}
 private fun showSounds(){onHome=false;soundPlayer.stop();var soundKey="vaca";val c=base("🎵 SONS","Toque no bichinho e ouça o som!");val name=TextView(this).apply{text="VACA";textSize=25f;gravity=Gravity.CENTER;setTextColor(Color.rgb(92,48,25))};val stage=AnimalStageView(this).apply{setSoundBoardMode(true);setAnimal("🐮");setOnClickListener{soundPlayer.play(soundKey);celebrate()}};c.addView(stage,LinearLayout.LayoutParams(-1,390));c.addView(name,p());val grid=GridLayout(this).apply{columnCount=2};animals.forEach{(e,n,k)->grid.addView(btn("$e  $n"){soundKey=k;name.text=n.uppercase();stage.setAnimal(e);stage.celebrate();soundPlayer.play(k)}.apply{textSize=22f;minHeight=112},GridLayout.LayoutParams().apply{width=0;columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);setMargins(6,6,6,6)})};c.addView(grid,LinearLayout.LayoutParams(-1,-2));c.addView(btn("🏠 Voltar ao mapa"){showHome()},p());set(c)}
 private fun showCare(step:Int){onHome=false;soundPlayer.stop();val s=listOf(Triple("🍎 Alimentar","Dê comida para a vaquinha","🍎 A maçã está pronta!"),Triple("🛁 Banho","Espuma e água para ficar limpinha","🫧 Banho gostoso!"),Triple("🧻 Secar","Seque bem a vaquinha","✨ Limpinha e cheirosa!"),Triple("🌙 Dormir","Hora de descansar","💤 Boa noite, vaquinha!"));val i=step.coerceIn(0,3);val c=base("❤️ CUIDAR",s[i].second);cow3d=Cow3DView(this).apply{setCareState(i)};c.addView(cow3d,LinearLayout.LayoutParams(-1,520));c.addView(TextView(this).apply{text="${i+1}/4  ${s[i].first}\n${s[i].third}";textSize=21f;gravity=Gravity.CENTER;setPadding(12,14,12,14);background=round(0xFFFFF1D0.toInt(),24f,0xFFD39A4B.toInt())},p());c.addView(btn(s[i].first){soundPlayer.play("vaca");if(i<3)showCare(i+1)else{stars+=5;hearts+=1;showCareDone()}},p());c.addView(btn("🏠 Voltar ao mapa"){showHome()},p());set(c)}
 private fun showCareDone(){onHome=false;soundPlayer.stop();val c=base("⭐ MUITO BEM!","Você cuidou da vaquinha!");c.addView(TextView(this).apply{text="+5 ⭐     +1 ❤️\n🐮💚";textSize=36f;gravity=Gravity.CENTER;setPadding(0,30,0,30)});c.addView(btn("🔁 Cuidar novamente"){showCare(0)},p());c.addView(btn("🏠 Voltar ao mapa"){showHome()},p());set(c)}
 private fun showFarm(step:Int,directCoop:Boolean=false){onHome=false;soundPlayer.stop();val i=step.coerceIn(0,2);val title=if(i==2)"🐔 GALINHEIRO" else "🚜 FAZENDINHA";val sub=when(i){0->"1. Regar a horta";1->"2. Colher os alimentos";else->"3. Pegar os ovos"};val c=base(title,sub);val scene=TextView(this).apply{text=when(i){0->"☀️   ☁️\n🌱 🌱 🌱 🌱\n🌱 🌱 🌱 🌱\n🟫🟫🟫🟫";1->"☀️  🦋\n🌽 🥕 🍅 🌽\n🥕 🌽 🍅 🥕\n🟫🟫🟫🟫";else->"🌳  🏡  🌳\n🐔    🐔\n🥚 🥚 🥚 🥚\n🧺"};textSize=47f;gravity=Gravity.CENTER;setPadding(0,25,0,25);background=round(0xDDFFF3CE.toInt(),30f,0xFFD39A4B.toInt())};c.addView(scene,LinearLayout.LayoutParams(-1,410));val progress=TextView(this).apply{text=when(i){0->"💧 0/3";1->"🧺 0/3";else->"🥚 0/4"};textSize=23f;gravity=Gravity.CENTER};c.addView(progress);var taps=0;val need=if(i==2)4 else 3;lateinit var action:Button;action=btn(when(i){0->"💧 REGAR";1->"🌽 COLHER";else->"🥚 PEGAR OVO"}){if(taps<need){taps++;when(i){0->{progress.text="💧 $taps/$need";scene.text=if(taps<need)"💦 💦\n🌱 🌱 🌱 🌱\n🌿 🌱 🌿 🌱\n🟫🟫🟫🟫" else "☀️ 🌈\n🌿 🌿 🌿 🌿\n🌽 🥕 🍅 🌽\n🟫🟫🟫🟫"};1->{progress.text="🧺 $taps/$need"};2->{soundPlayer.play("galinha");progress.text="🥚 $taps/$need"}};if(taps==need){action.isEnabled=false;val finish=i==2;c.addView(btn(if(finish)"⭐ TERMINAR" else "➡️ PRÓXIMO"){if(!finish)showFarm(i+1,false)else{stars+=if(directCoop)1 else 2;showReward(if(directCoop)1 else 2)}},p())}}};action.minHeight=110;c.addView(action,p());c.addView(btn("🏠 Voltar ao mapa"){showHome()},p());set(c)}
 private fun showReward(gained:Int){onHome=false;soundPlayer.stop();val c=base("🎉 TAREFA CONCLUÍDA!","Você ganhou +$gained ⭐");c.addView(TextView(this).apply{text="${"⭐".repeat(gained)}\n🌽🥕🍅  🧺🥚\n🐔💛";textSize=38f;gravity=Gravity.CENTER;setPadding(0,30,0,30)});c.addView(btn("🔁 Brincar novamente"){showFarm(0,false)},p());c.addView(btn("🏠 Voltar ao mapa"){showHome()},p());set(c)}
 private fun showLake(){onHome=false;soundPlayer.stop();val c=base("🦆 LAGO","Área bônus desbloqueada!");val lake=TextView(this).apply{text="☀️  🦋  ☁️\n🌳 🦆  🦆 🌳\n💧💧🐟💧💧\n🌿🌼🌿🌼🌿";textSize=44f;gravity=Gravity.CENTER;setPadding(0,35,0,35);background=round(0xAA7ED9F5.toInt(),36f,0xFF5AAB70.toInt());setOnClickListener{text="☀️  🦋  ☁️\n🌳 🦆 💦 🦆 🌳\n💧 🐟  🐟 💧\n🌿🌼🌿🌼🌿";Toast.makeText(this@MainActivity,"Splash! 🐟💦",Toast.LENGTH_SHORT).show()}};c.addView(lake,LinearLayout.LayoutParams(-1,520));c.addView(TextView(this).apply{text="👆 Toque no lago";textSize=18f;gravity=Gravity.CENTER});c.addView(btn("🏠 Voltar ao mapa"){showHome()},p());set(c)}
 private fun showLab(){onHome=false;soundPlayer.stop();selectedAccessory="";val c=base("👕 ARMÁRIO","Escolha um bichinho e monte o visual!");val h=FrameLayout(this).apply{background=round(0xFFFFE7BC.toInt(),32f,0xFFD39A4B.toInt())};stage2d=AnimalStageView(this).apply{visibility=View.GONE};cow3d=Cow3DView(this);h.addView(stage2d,FrameLayout.LayoutParams(-1,-1));h.addView(cow3d,FrameLayout.LayoutParams(-1,-1));c.addView(h,LinearLayout.LayoutParams(-1,500));status=TextView(this).apply{text="🐮 Vaca — sem roupa";textSize=19f;gravity=Gravity.CENTER};c.addView(status);val animalGrid=GridLayout(this).apply{columnCount=2};animals.forEach{(e,n,k)->animalGrid.addView(btn("$e $n"){selectedAnimal=k;selectedEmoji=e;selectedAccessory="";val cow=k=="vaca";cow3d.visibility=if(cow)View.VISIBLE else View.GONE;stage2d.visibility=if(cow)View.GONE else View.VISIBLE;cow3d.setAccessory("");if(!cow){stage2d.setAnimal(e);stage2d.celebrate()};status.text="$e $n — sem roupa";soundPlayer.play(k)},GridLayout.LayoutParams().apply{width=0;columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);setMargins(5,5,5,5)})};c.addView(animalGrid,LinearLayout.LayoutParams(-1,-2));c.addView(btn("🚫 SEM ROUPA"){selectedAccessory="";if(selectedAnimal=="vaca")cow3d.setAccessory("")else stage2d.setAnimal(selectedEmoji);status.text="$selectedEmoji Sem roupa"},p());val clothes=GridLayout(this).apply{columnCount=2};listOf("👒","🎀","🧢","👑","🕶️","🧣","🎩").forEach{a->clothes.addView(btn("$a Equipar"){selectedAccessory=a;if(selectedAnimal=="vaca")cow3d.setAccessory(a)else{stage2d.setAnimal(selectedEmoji," $a");stage2d.celebrate()};status.text="$selectedEmoji Visual $a ✨"},GridLayout.LayoutParams().apply{width=0;columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);setMargins(5,5,5,5)})};c.addView(clothes,LinearLayout.LayoutParams(-1,-2));c.addView(btn("📸 DESFILAR"){if(selectedAnimal=="vaca")cow3d.animate().scaleX(1.08f).scaleY(1.08f).setDuration(180).withEndAction{cow3d.animate().scaleX(1f).scaleY(1f).duration=180}else stage2d.celebrate();soundPlayer.play(selectedAnimal)},p());c.addView(btn("🏠 Voltar ao mapa"){showHome()},p());set(c)}
 @Deprecated("Deprecated in Java") override fun onBackPressed(){if(onHome)super.onBackPressed()else showHome()}
 override fun onDestroy(){soundPlayer.release();super.onDestroy()}
}
